"""Render the remix_ui_icons Dart libraries from the manifest and the lock.

The output is already in `dart format` style (80 columns, tall style), so a
regenerate-and-diff check needs no Dart toolchain and the workspace format
check sees no drift. `test_codegen.py` holds the formatting rules to that.
"""

from __future__ import annotations

import base64
import re
from dataclasses import dataclass

from manifest import Family, Glyph, LegacyIcon, Manifest

HEADER = (
    "// GENERATED CODE - DO NOT MODIFY BY HAND.\n"
    "// Generated by tool/icons/generate.py from tool/icons/manifest.yaml.\n"
)
WIDTH = 80
MASTER_RULE = (
    "Use the master closest to the rendered size: up to 12 px use the 12 px\n"
    "master, up to 16 px the 16 px master, and the 24 px master above that.\n"
    "Sizes below 12 px are not reviewed."
)
LABEL_RULE = (
    "Requires a visible text label at every size and in both styles. A\n"
    "tooltip or semantic label is not a substitute."
)


@dataclass(frozen=True)
class Library:
    path: str
    source: str


def _fits(line: str) -> bool:
    return len(line) <= WIDTH


def _call(indent: str, head: str, arguments: list[str], tail: str) -> str:
    """`head(arguments)tail`, on one line when it fits, else one per line."""

    single = f"{indent}{head}({', '.join(arguments)}){tail}"
    if _fits(single):
        return single + "\n"
    inner = indent + "  "
    body = "".join(f"{inner}{argument},\n" for argument in arguments)
    return f"{indent}{head}(\n{body}{indent}){tail}\n"


def _assignment(indent: str, declaration: str, value: str) -> str:
    """`declaration = value;`, split after `=` when it does not fit."""

    single = f"{indent}{declaration} = {value};"
    if _fits(single):
        return single + "\n"
    return f"{indent}{declaration} =\n{indent}    {value};\n"


def _doc(indent: str, text: str) -> str:
    lines = []
    for line in text.split("\n"):
        lines.append(f"{indent}///{' ' + line if line else ''}\n")
    return "".join(lines)


def _style_label(glyph: Glyph) -> str:
    return f"{glyph.concept.label}, {glyph.style} style, {glyph.master} px master."


def _preview(svg: bytes, label: str) -> str:
    """A self-contained SVG data URI for IDE hovers and API docs."""

    text = svg.decode("utf-8")
    text = re.sub(r"\s*<title>.*?</title>", "", text, flags=re.S)
    text = re.sub(r'\s(role|focusable)="[^"]*"', "", text)
    text = text.replace('fill="currentColor"', 'fill="#000"')
    text = text.replace(
        "<svg ", '<svg style="background-color:#fff;border-radius:2px" ', 1
    )
    text = re.sub(r">\s+<", "><", text).strip()
    encoded = base64.b64encode(text.encode("utf-8")).decode("ascii")
    return f"![{label}](data:image/svg+xml;base64,{encoded})"


def _dart_string(value: str) -> str:
    return "'" + value.replace("\\", "\\\\").replace("'", "\\'").replace("$", "\\$") + "'"


def family_library(
    manifest: Manifest,
    family: Family,
    codepoints: dict[str, int],
    svgs: dict[str, bytes],
) -> Library:
    glyphs = manifest.glyphs_of(family)
    concepts = [concept for concept in manifest.concepts if family.key in concept.families]
    example = concepts[0].name
    if any(concept.name == "search" for concept in concepts):
        example = "search"
    out = [HEADER, "\n", "import 'package:flutter/widgets.dart';\n", "\n"]
    out.append(
        _doc(
            "",
            f"The {family.label} family: {len(concepts)} concepts, each drawn in an\n"
            "outline and a filled style at native 24, 16, and 12 px masters.\n"
            "\n"
            "The bare name is the outline style at the 24 px master. `Filled`\n"
            "selects the filled style, and a `16` or `12` suffix a smaller master:\n"
            f"[{example}], [{example}Filled], [{example}16], [{example}Filled16],\n"
            f"[{example}12], and [{example}Filled12].\n"
            "\n"
            f"{MASTER_RULE}\n"
            "\n"
            "Refer to these constants directly, so a release build keeps only the\n"
            "glyphs an application uses.",
        )
    )
    out.append("@staticIconProvider\n")
    out.append(f"abstract final class {family.class_name} {{\n")
    out.append(f"  static const String _fontFamily = {_dart_string(manifest.font_family)};\n")
    out.append(f"  static const String _fontPackage = {_dart_string(manifest.package)};\n")
    for glyph in glyphs:
        out.append("\n")
        doc = _style_label(glyph)
        if glyph.requires_label:
            doc += f"\n\n{LABEL_RULE}"
        doc += "\n\n" + _preview(svgs[glyph.source], _style_label(glyph).removesuffix("."))
        out.append(_doc("  ", doc))
        arguments = [
            f"0x{codepoints[glyph.source]:04X}",
            "fontFamily: _fontFamily",
            "fontPackage: _fontPackage",
        ]
        if glyph.concept.rtl:
            arguments.append("matchTextDirection: true")
        out.append(_call("  ", f"static const IconData {glyph.member} = IconData", arguments, ";"))
    out.append("}\n")
    return Library(f"lib/src/generated/{family.key}_icons.dart", "".join(out))


def facade_library(manifest: Manifest) -> Library:
    family = manifest.default_family
    glyphs = manifest.glyphs_of(family)
    aliases = manifest.deprecated_aliases
    out = [HEADER, "\n", "import 'package:flutter/widgets.dart';\n", "\n"]
    out.append(f"import '{family.key}_icons.dart';\n\n")
    out.append(
        _doc(
            "",
            f"The default Remix icons: every [{family.class_name}] glyph, under the\n"
            "same name.\n"
            "\n"
            f"`RemixIcons.search` is [{family.class_name}.search]. Use\n"
            "[RoundedIcons] or [MonoIcons] directly for the other families.\n"
            "\n"
            f"{MASTER_RULE}\n"
            "\n"
            "The deprecated members are remix_ui_icons 0.1.x names whose concept has\n"
            "an exact replacement here. They render the new drawing and are removed\n"
            "in 2.0.0. Names without an exact replacement were removed in 1.0.0;\n"
            "MIGRATION.md lists each one with its closest Lucide icon.",
        )
    )
    out.append("@staticIconProvider\n")
    out.append("abstract final class RemixIcons {\n")
    first = True
    for glyph in glyphs:
        if not first:
            out.append("\n")
        first = False
        doc = f"{_style_label(glyph)} Same as [{family.class_name}.{glyph.member}]."
        if glyph.requires_label:
            doc += f"\n\n{LABEL_RULE}"
        out.append(_doc("  ", doc))
        out.append(
            _assignment(
                "  ",
                f"static const IconData {glyph.member}",
                f"{family.class_name}.{glyph.member}",
            )
        )
    for alias in aliases:
        out.append("\n")
        out.append(_doc("  ", f"The remix_ui_icons 0.1.x name for [{alias.target}]."))
        out.append(f"  @Deprecated('Use RemixIcons.{alias.target}. Removed in 2.0.0.')\n")
        out.append(
            _assignment(
                "  ",
                f"static const IconData {alias.name}",
                f"{family.class_name}.{alias.target}",
            )
        )
    out.append("}\n")
    return Library("lib/src/generated/remix_icons.dart", "".join(out))


def sets_library(manifest: Manifest) -> Library:
    out = [HEADER, "\n", "import 'package:flutter/widgets.dart';\n", "\n"]
    out.append("import '../remix_icon_set.dart';\n")
    for family in manifest.families:
        out.append(f"import '{family.key}_icons.dart';\n")
    for family in manifest.families:
        concepts = [concept for concept in manifest.concepts if family.key in concept.families]
        out.append("\n")
        out.append(
            _doc(
                "",
                f"Every [{family.class_name}] concept and style as a [RemixIconSet] of its\n"
                "three masters, for code that picks the master from a size at runtime.",
            )
        )
        out.append("@staticIconProvider\n")
        out.append(f"abstract final class {family.sets_class_name} {{\n")
        first = True
        for concept in concepts:
            for style in ("outline", "filled"):
                if not first:
                    out.append("\n")
                first = False
                suffix = "Filled" if style == "filled" else ""
                base = f"{concept.name}{suffix}"
                out.append(_doc("  ", f"{concept.label}, {style} style, at 12, 16, and 24 px."))
                out.append(
                    _call(
                        "  ",
                        f"static const RemixIconSet {base} = RemixIconSet",
                        [
                            f"{family.class_name}.{base}12",
                            f"{family.class_name}.{base}16",
                            f"{family.class_name}.{base}",
                        ],
                        ";",
                    )
                )
        out.append("}\n")
    return Library("lib/src/generated/icon_sets.dart", "".join(out))


def _string_list(values: list[str]) -> str:
    return "[" + ", ".join(_dart_string(value) for value in values) + "]"


def index_library(manifest: Manifest) -> Library:
    aliases: dict[str, list[str]] = {}
    for alias in manifest.deprecated_aliases:
        aliases.setdefault(alias.target, []).append(alias.name)
    out = [HEADER]
    out.append(
        "// Do not export this library from remix_ui_icons.dart: it refers to every\n"
        "// glyph, so importing it keeps the whole font in a release build.\n"
    )
    out.append("\n")
    out.append("import '../remix_icon_entry.dart';\n")
    for family in manifest.families:
        out.append(f"import '{family.key}_icons.dart';\n")
    out.append("\n")
    out.append(
        _doc(
            "",
            f"Every glyph in the package: {len(manifest.glyphs)} entries across the "
            f"{', '.join(family.label for family in manifest.families[:-1])}, and\n"
            f"{manifest.families[-1].label} families.",
        )
    )
    out.append("const List<RemixIconEntry> remixIconEntries = [\n")
    for glyph in manifest.glyphs:
        is_default = glyph.family == manifest.default_family
        fields = [
            f"name: {_dart_string(glyph.member)}",
            f"concept: {_dart_string(glyph.concept.name)}",
            f"label: {_dart_string(glyph.concept.label)}",
            f"family: RemixIconFamily.{glyph.family.key}",
            f"style: RemixIconStyle.{glyph.style}",
            f"master: {glyph.master}",
            f"icon: {glyph.family.class_name}.{glyph.member}",
            f"tags: {_string_list(list(glyph.concept.tags))}",
            f"aliases: {_string_list(aliases.get(glyph.member, []) if is_default else [])}",
            f"requiresLabel: {'true' if glyph.requires_label else 'false'}",
            f"since: {_dart_string(glyph.concept.since)}",
        ]
        out.append(_call("  ", "RemixIconEntry", fields, ","))
    out.append("];\n")
    return Library("lib/src/generated/icons_index.dart", "".join(out))


def libraries(
    manifest: Manifest, codepoints: dict[str, int], svgs: dict[str, bytes]
) -> list[Library]:
    return [
        *(family_library(manifest, family, codepoints, svgs) for family in manifest.families),
        facade_library(manifest),
        sets_library(manifest),
        index_library(manifest),
    ]


def public_api(manifest: Manifest) -> list[str]:
    """Every public generated member, one `Class.member` per line."""

    members = ["remixIconEntries"]
    for family in manifest.families:
        members += [f"{family.class_name}.{glyph.member}" for glyph in manifest.glyphs_of(family)]
    members += [f"RemixIcons.{glyph.member}" for glyph in manifest.glyphs_of(manifest.default_family)]
    members += [f"RemixIcons.{alias.name}" for alias in manifest.deprecated_aliases]
    for family in manifest.families:
        for concept in manifest.concepts:
            if family.key in concept.families:
                members += [
                    f"{family.sets_class_name}.{concept.name}",
                    f"{family.sets_class_name}.{concept.name}Filled",
                ]
    return sorted(members)


def legacy_targets(manifest: Manifest) -> dict[str, LegacyIcon]:
    return {icon.name: icon for icon in manifest.legacy}
